import math


def wilson_lower(k, n, z=1.96):
    if n == 0:
        return 0.0
    if k < 0 or k > n or n < 0:
        raise ValueError("k must satisfy 0 <= k <= n and n >= 0")
    p = k / n
    denom = 1 + z * z / n
    centre = (p + z * z / (2 * n)) / denom
    delta = z * math.sqrt(p * (1 - p) / n + z * z / (4 * n * n)) / denom
    lower = centre - delta
    return max(0.0, min(1.0, lower))

