def exponential_moving_average(values, alpha, initial=None):
    """Exponential moving average.

    Seeds from values[0] when initial is None (then updates over the
    rest); otherwise seeds from initial and updates over all values.
    """
    if not isinstance(values, list) or len(values) == 0:
        raise ValueError("values must be a non-empty list")
    if isinstance(alpha, bool) or not isinstance(alpha, (int, float)):
        raise ValueError("alpha must be a number")
    if alpha <= 0 or alpha > 1:
        raise ValueError("alpha must satisfy 0 < alpha <= 1")
    if initial is None:
        ema = float(values[0])
        result = [ema]
        rest = values
    else:
        ema = float(initial)
        result = []
        rest = values
    for x in rest:
        ema = alpha * float(x) + (1 - alpha) * ema
        result.append(ema)
    return result

